package com.cenedu.backend.ai.problem.render;
import static org.assertj.core.api.Assertions.*; import com.cenedu.backend.ai.problem.adapter.SafeSvgSanitizer; import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.*; import java.util.*; import org.junit.jupiter.api.Test;
class SemanticFamilyValueTest { private final DiagramViewport v=new DiagramViewport(640,240,16); private final DiagramStyle s=new DiagramStyle("#000000","#FFFFFF","#FF0000",1,"sans-serif",12); @Test void solidLabelUsesSemanticValue(){var d=new SolidGeometryDiagramSpecV1(1,"S",DiagramKind.SOLID_GEOMETRY,v,s,SolidGeometryKind.PRISM,"W",null,null,null,null,null,List.of(new SolidLabelSpec("L","W","width")));var svg=new ProblemDiagramRenderer(new SafeSvgSanitizer()).render(d,new DiagramRenderContext(Map.of("W",new SemanticResolvedValue(SemanticValueType.INTEGER,"12","cm")))).svg();assertThat(svg).contains("width 12");} @Test void planePointUsesSemanticCoordinates(){var d=new PlaneGeometryDiagramSpecV1(1,"P",DiagramKind.PLANE_GEOMETRY,v,s,List.of(new PlanePointSpec("A","X","Y","A")),List.of(),List.of(),List.of(),List.of(),List.of(),List.of());var svg=new ProblemDiagramRenderer(new SafeSvgSanitizer()).render(d,new DiagramRenderContext(Map.of("X",new SemanticResolvedValue(SemanticValueType.INTEGER,"3",null),"Y",new SemanticResolvedValue(SemanticValueType.INTEGER,"4",null)))).svg();assertThat(svg).contains("cx=\"66\"").contains("cy=\"76\"");} }
